package core

import (
	"maps"
	"path/filepath"
	"slices"
	"testing"

	"github.com/stretchr/testify/assert"
)

func scriptContexts(root string, files map[string]string) []*FileContext {
	var contexts []*FileContext
	for rel, content := range files {
		contexts = append(contexts, NewFileContext(filepath.Join(root, rel), root, []byte(content), DefaultConfig()))
	}
	return contexts
}

// Names come from the imports of hand-written files alone: a generated file
// importing another generated one uses nothing, and a module named like the
// generated one with a further suffix (api.service) is another module.
func TestGeneratedTSImports(t *testing.T) {
	root := t.TempDir()
	files := map[string]string{
		"src/api.ts":         "// Code generated by typegen. DO NOT EDIT.\n\nexport interface Item { id: string }\nexport interface Order { id: string }\nexport interface Unused { id: string }\n",
		"src/more.ts":        "// Code generated by typegen. DO NOT EDIT.\n\nimport type { Unused } from './api'\n\nexport type Alias = Unused\n",
		"src/api.service.ts": "export interface Service { id: string }\n",
		"src/view.js":        "import api, { Item } from './api.js'\nimport { Service } from './api.service'\n",
		"src/order.ts":       "import type { Order } from 'app/src/api'\n",
	}
	got := slices.Sorted(maps.Keys(GeneratedTSImports(scriptContexts(root, files))))
	assert.Equal(t, []string{"Item", "Order"}, got)

	delete(files, "src/api.ts")
	delete(files, "src/more.ts")
	assert.Empty(t, GeneratedTSImports(scriptContexts(root, files)))
}
